can happen when splicing as of commit 2b514574f7e8 ("net: af_unix:
implement splice for stream af_unix sockets").

Also collapse two branches using a bitwise or.

Cc: stable@vger.kernel.org
Fixes: 4d1442979e4a ("af_unix: don't post cmsg for SO_INQ unless explicitly asked for")
Link: https://lore.kernel.org/netdev/willemdebruijn.kernel.24d8030f7a3de@gmail.com/
Signed-off-by: Willem de Bruijn <willemb@google.com>
Reviewed-by: Jens Axboe <axboe@kernel.dk>
Reviewed-by: Eric Dumazet <edumazet@google.com>
Reviewed-by: Kuniyuki Iwashima <kuniyu@google.com>
Link: https://patch.msgid.link/20260106150626.3944363-1-willemdebruijn.kernel@gmail.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The callee (`unix_stream_read_generic`) unconditionally sets `msg->msg_get_inq` to 1 when `u->recvmsg_inq` is true, without checking if `msg` (i.e., `state->msg`) is NULL. This leads to a NULL pointer dereference when the function is invoked during splice operations (introduced by commit 2b514574f7e8), where `state->msg` is NULL. Additionally, the design incorrectly writes to an input field (`msg_get_inq`) that should only be set by the caller.

Here is the patch:

 static int unix_stream_read_generic(struct unix_stream_read_state *state,
 				    bool freezable)
 {
 	int noblock = state->flags & MSG_DONTWAIT;
 	struct socket *sock = state->socket;
 	struct msghdr *msg = state->msg;
 	struct sock *sk = sock->sk;
 	size_t size = state->size;
 	int flags = state->flags;
 	bool check_creds = false;
 	struct scm_cookie scm;
 	unsigned int last_len;
 	struct unix_sock *u;
 	int copied = 0;
-	bool do_cmsg;
 	int err = 0;
 	long timeo;
 	int target;
 	int skip;

 	if (unlikely(READ_ONCE(sk->sk_state) != TCP_ESTABLISHED)) {
 		err = -EINVAL;
 		goto out;
 	}

 	if (unlikely(flags & MSG_OOB)) {
 		err = -EOPNOTSUPP;
 #if IS_ENABLED(CONFIG_AF_UNIX_OOB)
 		err = unix_stream_recv_urg(state);
 #endif
 		goto out;
 	}

 	target = sock_rcvlowat(sk, flags & MSG_WAITALL, size);
 	timeo = sock_rcvtimeo(sk, noblock);

 	memset(&scm, 0, sizeof(scm));

 	u = unix_sk(sk);

-	do_cmsg = READ_ONCE(u->recvmsg_inq);
-	if (do_cmsg)
-		msg->msg_get_inq = 1;
 redo:
 	/* Lock the socket to prevent queue disordering
 	 * while sleeps in memcpy_tomsg
 	 */
 	mutex_lock(&u->iolock);

 	skip = max(sk_peek_offset(sk, flags), 0);

 	do {
 		struct sk_buff *skb, *last;
 		int chunk;

 		unix_state_lock(sk);
 		if (sock_flag(sk, SOCK_DEAD)) {
 			err = -ECONNRESET;
 			goto unlock;
 		}
 		last = skb = skb_peek(&sk->sk_receive_queue);
 		last_len = last ? last->len : 0;

 again:
 #if IS_ENABLED(CONFIG_AF_UNIX_OOB)
 		if (skb) {
 			skb = manage_oob(skb, sk, flags, copied);
 			if (!skb && copied) {
 				unix_state_unlock(sk);
 				break;
 			}
 		}
 #endif
 		if (skb == NULL) {
 			if (copied >= target)
 				goto unlock;

 			/*
 			 *	POSIX 1003.1g mandates this order.
 			 */

 			err = sock_error(sk);
 			if (err)
 				goto unlock;
 			if (sk->sk_shutdown & RCV_SHUTDOWN)
 				goto unlock;

 			unix_state_unlock(sk);
 			if (!timeo) {
 				err = -EAGAIN;
 				break;
 			}

 			mutex_unlock(&u->iolock);

 			timeo = unix_stream_data_wait(sk, timeo, last,
 						      last_len, freezable);

 			if (signal_pending(current)) {
 				err = sock_intr_errno(timeo);
 				scm_destroy(&scm);
 				goto out;
 			}

 			goto redo;
 unlock:
 			unix_state_unlock(sk);
 			break;
 		}

 		while (skip >= unix_skb_len(skb)) {
 			skip -= unix_skb_len(skb);
 			last = skb;
 			last_len = skb->len;
 			skb = skb_peek_next(skb, &sk->sk_receive_queue);
 			if (!skb)
 				goto again;
 		}

 		unix_state_unlock(sk);

 		if (check_creds) {
 			/* Never glue messages from different writers */
 			if (!unix_skb_scm_eq(skb, &scm))
 				break;
 		} else if (unix_may_passcred(sk)) {
 			/* Copy credentials */
 			unix_skb_to_scm(skb, &scm);
 			check_creds = true;
 		}

 		/* Copy address just once */
 		if (msg && msg->msg_name) {
 			DECLARE_SOCKADDR(struct sockaddr_un *, sunaddr, msg->msg_name);

 			unix_copy_addr(msg, skb->sk);
 			BPF_CGROUP_RUN_PROG_UNIX_RECVMSG_LOCK(sk, msg->msg_name,
 							      &msg->msg_namelen);

 			sunaddr = NULL;
 		}

 		chunk = min_t(unsigned int, unix_skb_len(skb) - skip, size);
 		chunk = state->recv_actor(skb, skip, chunk, state);
 		if (chunk < 0) {
 			if (copied == 0)
 				copied = -EFAULT;
 			break;
 		}
 		copied += chunk;
 		size -= chunk;

 		/* Mark read part of skb as used */
 		if (!(flags & MSG_PEEK)) {
 			UNIXCB(skb).consumed += chunk;

 			sk_peek_offset_bwd(sk, chunk);

 			if (UNIXCB(skb).fp) {
 				scm_stat_del(sk, skb);
 				unix_detach_fds(&scm, skb);
 			}

 			if (unix_skb_len(skb))
 				break;

 			spin_lock(&sk->sk_receive_queue.lock);
 			WRITE_ONCE(u->inq_len, u->inq_len - skb->len);
 			__skb_unlink(skb, &sk->sk_receive_queue);
 			spin_unlock(&sk->sk_receive_queue.lock);

 			consume_skb(skb);

 			if (scm.fp)
 				break;
 		} else {
 			/* It is questionable, see note in unix_dgram_recvmsg.
 			 */
 			if (UNIXCB(skb).fp)
 				unix_peek_fds(&scm, skb);

 			sk_peek_offset_fwd(sk, chunk);

 			if (UNIXCB(skb).fp)
 				break;

 			skip = 0;
 			last = skb;
 			last_len = skb->len;
 			unix_state_lock(sk);
 			skb = skb_peek_next(skb, &sk->sk_receive_queue);
 			if (skb)
 				goto again;
 			unix_state_unlock(sk);
 			break;
 		}
 	} while (size);

